36	<script>
37	(function() {
38	  var filterEl = document.getElementById('lang-filter');
39	  if (!filterEl) return;
40	
41	  function applyFilter(lang) {
42	    filterEl.querySelectorAll('.lang-filter-btn').forEach(function(b) {
43	      b.classList.toggle('active', b.dataset.lang === lang);
44	    });
45	
46	    document.querySelectorAll('.blog-year-block').forEach(function(block) {
47	      var visibleCount = 0;
48	      block.querySelectorAll('.post-list-item').forEach(function(item) {
49	        var show = lang === 'all' || item.dataset.postLang === lang;
50	        item.style.display = show ? '' : 'none';
51	        if (show) visibleCount++;
52	      });
53	      block.style.display = visibleCount > 0 ? '' : 'none';
54	    });
55	  }
56	
57	  filterEl.addEventListener('click', function(e) {
58	    var btn = e.target.closest('.lang-filter-btn');
59	    if (!btn) return;
60	    var lang = btn.dataset.lang;
61	    applyFilter(lang);
62	    var url = new URL(window.location);
63	    if (lang === 'all') { url.searchParams.delete('lang'); }
64	    else { url.searchParams.set('lang', lang); }
65	    history.replaceState(null, '', url);
66	  });
67	
68	  // Deep-link support: /blog/?lang=en or /blog/?lang=my
69	  var requested = new URLSearchParams(window.location.search).get('lang');
70	  if (requested === 'en' || requested === 'my') {
71	    applyFilter(requested);
72	  }
73	})();
74	</script>
